<template>
  <TouchlessWidgetWrapper
    :title="$t('po_match_explanation_title')"
    icon="mdi:sitemap-outline"
    :loading="loading"
    :error="Boolean(error)"
    :error-message="error"
    data-test="po-match-explanation-panel"
    @retry="load"
  >
    <template #header-actions>
      <q-badge
        v-if="modeBadge"
        outline
        color="primary"
        :label="modeBadge"
        data-test="po-match-mode-badge"
      />
    </template>

    <div v-if="explanation" class="po-panel">
      <!--
        The rule set first, and in words before pictures: version, who owns it
        and when it was published. A diagram of a rule set nobody can identify
        is a diagram of nothing.
      -->
      <dl class="po-panel__meta" data-test="po-match-ruleset-meta">
        <template v-if="explanation.ruleset?.doc_type">
          <dt>{{ $t('po_match_ruleset_doc_type') }}</dt>
          <dd class="po-panel__mono">{{ explanation.ruleset?.doc_type }}</dd>
        </template>
        <template v-if="explanation.ruleset?.version != null">
          <dt>{{ $t('po_match_ruleset_version') }}</dt>
          <dd class="po-panel__mono">v{{ explanation.ruleset?.version }}</dd>
        </template>
        <template v-if="sourceOrgText">
          <dt>{{ $t('po_match_ruleset_source') }}</dt>
          <dd>{{ sourceOrgText }}</dd>
        </template>
        <template v-if="publishedAt">
          <dt>{{ $t('po_match_ruleset_published') }}</dt>
          <dd>{{ publishedAt }}</dd>
        </template>
        <template v-if="matchQuantityOn">
          <dt>{{ $t('po_match_setting_quantity_on') }}</dt>
          <dd class="po-panel__mono">{{ matchQuantityOn }}</dd>
        </template>
        <template v-for="row in toleranceRows" :key="row.key">
          <dt>{{ row.label }}</dt>
          <dd class="po-panel__mono">
            {{ row.value }}
            <q-badge
              v-if="row.fallback"
              outline
              color="warning"
              class="q-ml-xs"
              :label="$t('po_match_setting_engine_default')"
            />
          </dd>
        </template>
      </dl>

      <!--
        The API says WHICH of five situations the rule set is in, and the
        sentence comes with it in both languages. Deriving it here from
        `parse_error` was the bug: "nobody activated a version" and "the
        active TOML will not parse" arrive as the same field and mean opposite
        things — one is two clicks on the settings page, the other is a
        developer.
      -->
      <p
        v-if="rulesetStateNote"
        class="po-panel__note"
        data-test="po-match-ruleset-state-note"
      >
        {{ rulesetStateNote }}
      </p>

      <PoMatchDecisionFlow
        :stages="explanation.stages"
        :mode="explanation.mode"
        :terminal="explanation.terminal"
        :distribution="explanation.distribution"
        :trace-missing-label="explanation.trace_missing_label"
        :compact="compact"
        @select-pass="onSelectPass"
      />

      <PoMatchWhyBlocked
        v-if="explanation.mode === 'document'"
        class="q-mt-md"
        :explanation="explanation.explanation"
        :ruleset="explanation.ruleset"
        :trace-missing-label="explanation.trace_missing_label"
      />

      <!--
        The cluster's arithmetic, stated so it can be checked: the bars plus
        the documents with no usable stop point equal the sample size.
      -->
      <p
        v-if="explanation.distribution"
        class="po-panel__note"
        data-test="po-match-distribution-total"
      >
        {{
          $t('po_match_cluster_total', {
            attributed: explanation.distribution.attributed_count,
            sampled: explanation.distribution.sampled_doc_count,
            unattributed: explanation.distribution.unattributed_count,
          })
        }}
      </p>

      <a
        v-if="explanation.ruleset?.settings_deep_link"
        class="po-panel__link"
        :href="explanation.ruleset?.settings_deep_link || ''"
        data-test="po-match-settings-link"
      >
        {{ $t('po_match_open_settings') }}
      </a>
    </div>
  </TouchlessWidgetWrapper>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import PoMatchDecisionFlow from './PoMatchDecisionFlow.vue';
import PoMatchWhyBlocked from './PoMatchWhyBlocked.vue';
import TouchlessWidgetWrapper from './TouchlessWidgetWrapper.vue';
import PoMatchExplanationService, {
  isValidPoMatchResponse,
  pickPoMatchText,
  type PoMatchExplanationResponse,
} from 'src/services/analytics/PoMatchExplanationService';
import { logger } from 'src/utils/logger';

interface ToleranceRow {
  key: string;
  label: string;
  value: string;
  fallback: boolean;
}

/**
 * The one place the three PO-match views are fetched from.
 *
 * The document trace, the cluster card and the supplier diagnosis all want the
 * same panel with a different subject, and each of them writing its own load /
 * error / retry cycle would be three chances for them to disagree about what
 * "no trace" looks like. The subject is a prop; everything else is identical
 * by construction.
 *
 * Options API with `defineComponent`, no `<script setup>` — the house style.
 */
export default defineComponent({
  name: 'PoMatchExplanationPanel',

  components: {
    PoMatchDecisionFlow,
    PoMatchWhyBlocked,
    TouchlessWidgetWrapper,
  },

  props: {
    /**
     * What to explain. `ruleset` needs no subject at all — that is the view a
     * consultant opens first, and it must not depend on finding a document.
     */
    mode: {
      type: String as PropType<'ruleset' | 'document' | 'cluster'>,
      default: 'ruleset',
    },
    docId: { type: String, default: '' },
    issueSignature: { type: String, default: '' },
    docType: { type: String, default: 'INVOICE' },
    windowDays: { type: Number, default: 30 },
    compact: { type: Boolean, default: false },
  },

  emits: ['select-pass', 'loaded'],

  data() {
    return {
      loading: false,
      error: '',
      explanation: null as PoMatchExplanationResponse | null,
      service: new PoMatchExplanationService(),
    };
  },

  computed: {
    locale(): string {
      return String(this.$i18n?.locale || 'en');
    },

    modeBadge(): string {
      if (!this.explanation) return '';
      return this.$t(`po_match_mode_${this.explanation.mode}`);
    },

    sourceOrgText(): string {
      const source = this.explanation?.ruleset?.source_org;
      if (source === 'org') return this.$t('po_match_ruleset_source_org');
      if (source === 'default') {
        return this.$t('po_match_ruleset_source_default');
      }
      return '';
    },

    publishedAt(): string {
      const raw = this.explanation?.ruleset?.published_at;
      if (!raw) return '';
      const parsed = new Date(raw);
      return Number.isNaN(parsed.getTime())
        ? String(raw)
        : parsed.toLocaleDateString(this.locale);
    },

    /**
     * What to say about the rule set's state, or nothing.
     *
     * Silent for `published`: a reader looking at the rules that decide does
     * not need to be told they decide. Every other state is worth a line, and
     * the line is the API's own — composed server-side in both languages, so
     * there is no key to invent and nothing to keep in sync.
     */
    rulesetStateNote(): string {
      const ruleset = this.explanation?.ruleset;
      if (!ruleset) return '';
      if (ruleset.state === 'published') return '';
      const label = pickPoMatchText(ruleset.state_label, this.locale);
      if (label) return label;
      // An older backend sends no state. Fall back to the old behaviour
      // rather than going silent about a rule set that could not be read.
      return ruleset.parse_error ? this.$t('po_match_ruleset_unreadable') : '';
    },

    matchQuantityOn(): string {
      const setting = this.explanation?.ruleset?.settings?.match_quantity_on;
      return setting?.value == null ? '' : String(setting.value);
    },

    /**
     * The tolerances, each saying whether the customer configured it.
     *
     * A setting the rule set does not configure is shown as NOT configured,
     * with the number that decides in its place — never with the matcher's
     * built-in default, which this application does not own and the settings
     * page does not show.
     */
    toleranceRows(): ToleranceRow[] {
      const settings = this.explanation?.ruleset?.settings || {};
      const wanted: Array<[string, string]> = [
        ['default_tolerance', 'po_match_setting_default_tolerance'],
        ['default_quantity_tolerance', 'po_match_setting_quantity_tolerance'],
        ['default_unit_price_tolerance', 'po_match_setting_price_tolerance'],
      ];
      const rows: ToleranceRow[] = [];
      for (const [key, label] of wanted) {
        const setting = settings[key];
        if (!setting) continue;
        const effective = setting.effective_value;
        if (effective == null && !setting.configured) continue;
        rows.push({
          key,
          label: this.$t(label),
          value:
            setting.formatted || (effective == null ? '' : String(effective)),
          fallback: !setting.configured,
        });
      }
      return rows;
    },
  },

  watch: {
    mode: 'load',
    docId: 'load',
    issueSignature: 'load',
    windowDays: 'load',
  },

  mounted() {
    void this.load();
  },

  methods: {
    async load(): Promise<void> {
      this.loading = true;
      this.error = '';
      try {
        const response = await this.fetch();
        if (!isValidPoMatchResponse(response)) {
          // A response without `stages` is no diagram at all. Caught here
          // rather than as a render error, so the reader sees the panel's own
          // retry instead of a blank card.
          throw new Error('malformed po-match explanation');
        }
        this.explanation = response;
        this.$emit('loaded', response);
      } catch (error) {
        logger.error('PoMatchExplanationPanel: load failed', error);
        this.explanation = null;
        this.error = this.$t('po_match_load_failed');
      } finally {
        this.loading = false;
      }
    },

    fetch(): Promise<PoMatchExplanationResponse> {
      if (this.mode === 'document' && this.docId) {
        return this.service.getDocument(this.docId);
      }
      if (this.mode === 'cluster' && this.issueSignature) {
        return this.service.getCluster(this.issueSignature, this.windowDays);
      }
      return this.service.getRuleset(this.docType);
    },

    onSelectPass(payload: unknown): void {
      this.$emit('select-pass', payload);
    },
  },
});
</script>

