<template>
  <div class="po-why" data-test="po-match-why-blocked">
    <div v-if="sentence" class="po-why__lede" data-test="po-match-why-sentence">
      <span class="po-why__eyebrow">{{ $t('po_match_why_title') }}</span>
      <p class="po-why__text">{{ sentence }}</p>
    </div>

    <p v-else class="po-why__empty" data-test="po-match-why-empty">
      {{ emptyText }}
    </p>

    <!--
      The values the sentence is made of, laid out so a reader can check it
      against the document. Every cell comes from `explanation.fields`; a field
      the trace did not carry is left out entirely rather than filled with a
      dash that looks like a measured zero.
    -->
    <dl
      v-if="rows.length"
      class="po-why__values"
      data-test="po-match-why-values"
    >
      <template v-for="row in rows" :key="row.key">
        <dt>{{ row.label }}</dt>
        <dd :class="{ 'po-why__mono': row.mono }">{{ row.value }}</dd>
      </template>
    </dl>

    <p
      v-if="incomplete"
      class="po-why__note"
      data-test="po-match-why-incomplete"
    >
      {{ $t('po_match_why_incomplete') }}
    </p>

    <p
      v-if="provenance"
      class="po-why__note"
      data-test="po-match-why-provenance"
    >
      {{ provenance }}
    </p>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import {
  pickPoMatchText,
  type PoMatchExplanationBlock,
  type PoMatchRuleset,
  type PoMatchText,
} from 'src/services/analytics/PoMatchExplanationService';

interface ValueRow {
  key: string;
  label: string;
  value: string;
  mono: boolean;
}

/**
 * "Warum lief dieses Dokument nicht durch?" — the answer in normal words.
 *
 * Two halves, and the split is the whole design. The paragraph is the sentence
 * the API composed from the recorded trace and sent in EN and DE; this
 * component picks the reader's language and prints it. The table underneath is
 * the DATA that sentence was made of — stage and rule, the compared column,
 * the expected and actual value, the tolerance in force and the pass the line
 * pair was discarded in — so the reader can check the sentence against the
 * document rather than believe it.
 *
 * Nothing here composes a claim. A field the trace does not carry produces no
 * row, and a document with no trace produces the honest "we did not record
 * this" instead of a plausible paragraph. That restraint is the feature: an
 * explanation with one invented number in it is worse than no explanation.
 */
export default defineComponent({
  name: 'PoMatchWhyBlocked',

  props: {
    explanation: {
      type: Object as PropType<PoMatchExplanationBlock | null>,
      default: null,
    },
    ruleset: {
      type: Object as PropType<PoMatchRuleset | null>,
      default: null,
    },
    /** Why there is no trace, already localised by the API. */
    traceMissingLabel: {
      type: Object as PropType<PoMatchText | null>,
      default: null,
    },
  },

  computed: {
    locale(): string {
      return String(this.$i18n?.locale || 'en');
    },

    sentence(): string {
      return pickPoMatchText(this.explanation?.text, this.locale);
    },

    /**
     * What to say when there is no sentence.
     *
     * Two different situations, two different sentences: a document whose
     * trace we do not have, and a document that simply matched. Collapsing
     * them into one message would tell a customer their working document is
     * missing data.
     */
    emptyText(): string {
      const missing = pickPoMatchText(this.traceMissingLabel, this.locale);
      return missing
        ? `${this.$t('po_match_why_no_trace')} — ${missing}`
        : this.$t('po_match_why_nothing_blocked');
    },

    incomplete(): boolean {
      return Boolean(this.explanation && this.explanation.complete === false);
    },

    provenance(): string {
      const version = this.ruleset?.version;
      const hash = this.ruleset?.short_hash;
      if (version == null && !hash) return '';
      const parts = [this.$t('po_match_why_ruleset')];
      if (version != null) parts.push(`v${version}`);
      if (hash) parts.push(hash);
      return parts.join(' · ');
    },

    rows(): ValueRow[] {
      const fields = this.explanation?.fields;
      if (!fields) return [];
      const rows: ValueRow[] = [];

      const stageLabel = pickPoMatchText(fields.stage_label, this.locale);
      if (fields.stage_no != null || stageLabel) {
        rows.push({
          key: 'stage',
          label: this.$t('po_match_why_stage'),
          value: [
            fields.stage_no != null
              ? `${this.$t('po_match_why_stage_no')} ${fields.stage_no}`
              : '',
            stageLabel,
          ]
            .filter(Boolean)
            .join(' · '),
          mono: false,
        });
      }
      if (fields.rule) {
        rows.push({
          key: 'rule',
          label: this.$t('po_match_why_rule'),
          value: String(fields.rule),
          mono: true,
        });
      }
      if (fields.column) {
        rows.push({
          key: 'column',
          label: this.$t('po_match_why_column'),
          value: String(fields.column),
          mono: true,
        });
      }
      if (fields.expected != null) {
        rows.push({
          key: 'expected',
          label: this.$t('po_match_why_expected'),
          value: String(fields.expected),
          mono: true,
        });
      }
      if (fields.actual != null) {
        rows.push({
          key: 'actual',
          label: this.$t('po_match_why_actual'),
          value: String(fields.actual),
          mono: true,
        });
      }
      if (fields.tolerance != null) {
        rows.push({
          key: 'tolerance',
          label: this.$t('po_match_why_tolerance'),
          value: fields.tolerance_type
            ? `${fields.tolerance} (${fields.tolerance_type})`
            : String(fields.tolerance),
          mono: true,
        });
      }
      const discarded = pickPoMatchText(fields.discarded_in_pass, this.locale);
      if (discarded) {
        rows.push({
          key: 'pass',
          label: this.$t('po_match_why_pass'),
          value: discarded,
          mono: false,
        });
      }
      if (fields.failed_pairs != null) {
        rows.push({
          key: 'pairs',
          label: this.$t('po_match_why_pairs'),
          value: String(fields.failed_pairs),
          mono: true,
        });
      }
      return rows;
    },
  },
});
</script>

